import { Component, input, output } from '@angular/core';

@Component({
  selector: 'app-star-rating',
  template: `
    @for (star of stars; track star) {
      <button type="button" class="text-2xl text-slate-300" (click)="select(star)" [class.text-amber-500]="star <= value">★</button>
    }
  `,
})
export class StarRating {
  value = input(0);
  max = input(5);
  stars = Array.from({ length: this.max() }, (_, i) => i + 1);
  changed = output<number>();

  select(star: number) {
    this.value = star;
  }
}

import { Component, signal } from '@angular/core';
import { StarRating } from './star-rating';

@Component({
  selector: 'app-rating-demo',
  imports: [StarRating],
  template: `
    <app-star-rating value="rating()" [max]="10" (change)="rating.set($event)" />
    <p>You rated {{ rating() }} / 10</p>
  `,
})
export class RatingDemo {
  rating = signal(3);
}
